// generar_279_rutinas_agrupadas.js
// CHIQUI Entre Señales — Rutinas de cuidado agrupadas por categoría
//
// Las "Rutinas de cuidado" en Análisis eran una lista plana ordenada
// por urgencia con un "Ver todas". Ahora se agrupan por categoría,
// igual que el registro diario y el calendario, para que la app se
// lea con la misma estructura en todas partes:
//
//   🩺 Veterinario y salud        [1 pendiente]  4  ›
//   🛡️ Prevención                                 4  ›
//   🍽️ Alimentación                                4  ▾
//        (rutinas del grupo, desplegadas)
//   🧼 Higiene y bienestar        [2 pendientes] 6  ›
//   🐱 Arenero  (solo gatos)                       3  ›
//
// Cada grupo es desplegable (cerrado por defecto). Dentro conserva el
// orden por urgencia (lo más atrasado primero).
//
// PARA NO PERDER LO URGENTE al agrupar: el encabezado de cada grupo
// muestra un contador naranjo "N pendientes" cuando alguna rutina del
// grupo está atrasada o vence hoy. Así lo importante se ve aunque el
// grupo esté cerrado — no queda escondido dentro de un desplegable.
//
// La distribución de franjas de alimentación (mañana/tarde/noche) y
// todo lo demás de cada rutina se mantiene igual, solo cambia cómo se
// organizan en pantalla.
//
// No hay SQL. Solo reescribe app/analisis/page.tsx.
//
// Uso:
//   node generar_279_rutinas_agrupadas.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: 'app/analisis/page.tsx',
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 1 archivo escrito. git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
